    "encounterPosition": 4,
    "exceptional": false,
    "exile": false,
    "factionName": "Mythos",
    "flavor": "The trees close in as you follow Bertie's trail deeper into the forest.",
    "flavorZh": "你追随伯蒂的踪迹深入森林，四周的树木将你包围。",
    "healthPerInvestigator": false,
    "hidden": false,
    "icons": {},
