    "imagesrc": "/bundles/cards/53045.png",
    "klass": "mythos",
    "localeStatus": "complete",
    "myriad": false,
    "name": "Return to Heart of the Elders, Part 1",
    "nameZh": "重返久远腹地，第一部分",
