    "name": "The True Culprit (v. I)",
    "nameZh": "真凶(版本一)",
    "originalCode": "84043",
    "pack": "hotel",
    "packName": "Murder at the Excelsior Hotel",
    "permanent": false,
    "position": 43,
    "provenanceId": "84043",
