    "localeStatus": "complete",
    "myriad": false,
    "name": "The Lonely Caverns",
    "nameZh": "孤独的洞穴群",
    "originalCode": "04211",
    "pack": "hote",
    "packName": "Heart of the Elders",
    "permanent": false,
    "position": 211,
    "provenanceId": "04211",
    "quantity": 1,
