    "illustrator": "Reiko Murakami",
    "imageStatus": "unresolved",
    "imagesrc": "/bundles/cards/04318.png",
    "klass": "mythos",
    "localeStatus": "complete",
    "myriad": false,
    "name": "Worlds Beyond",
    "nameZh": "彼端的世界",
    "originalCode": "04318",
    "pack": "sha",
    "packName": "Shattered Aeons",
    "permanent": false,
    "position": 318,
