    "encounterName": "Lost in the Night",
    "encounterPosition": 4,
    "exceptional": false,
    "exile": false,
    "factionName": "Mythos",
    "flavor": "You set out to search for the missing team members, hoping to find them before daybreak...",
    "flavorZh": "你开始寻找失踪的队员，希望在黎明前找到他们……",
    "healthPerInvestigator": false,
    "hidden": false,
    "icons": {},
    "illustrator": "Juan Carlos Barquet",
    "imageStatus": "unresolved",
    "imagesrc": "/bundles/cards/08526.png",
    "klass": "mythos",
    "localeStatus": "complete",
    "myriad": false,
    "name": "The Lost Expedition",
    "nameZh": "失踪队员",
    "originalCode": "08526",
    "pack": "eoec",
    "packName": "Edge of the Earth Campaign Expansion",
    "permanent": false,
