    "factionName": "Mythos",
    "flavor": "You finally have her in your sights!",
    "flavorZh": "你终于要逮住她了！",
    "healthPerInvestigator": false,
    "hidden": false,
    "icons": {},
    "illustrator": "Drazenka Kimpel",
