    "myriad": false,
    "name": "If It Bleeds...",
    "nameZh": "如果它会流血……",
    "originalCode": "09614",
    "pack": "tskc",
    "packName": "The Scarlet Keys Campaign Expansion",
    "permanent": false,
    "position": 114,
    "provenanceId": "09614",
