    "encounterName": "Without a Trace",
    "encounterPosition": 4,
    "exceptional": false,
    "exile": false,
    "factionName": "Mythos",
    "flavor": "<span class='tsk-glyphs'>come you did</span> what\n<span class='tsk-glyphs'>do to</span> here\n?<span class=''>again</span>",
    "flavorZh": "---- 什么 --- 这里 ---",
